const retentionReviewCandidates = `-- name: RetentionReviewCandidates :many
SELECT (p).tenant_id::uuid AS tenant_id,
       (p).category::text AS category,
       (p).candidate_count::bigint AS candidate_count
FROM retention_review_candidates(NULL::uuid) AS p
`

type RetentionReviewCandidatesRow struct {
	TenantID       uuid.UUID
	Category       string
	CandidateCount int64
}

// Cross-tenant review used by the scheduled job. It writes one
// retention.reviewed audit event per tenant with a confirmed policy.
func (q *Queries) RetentionReviewCandidates(ctx context.Context) ([]RetentionReviewCandidatesRow, error) {
	rows, err := q.db.QueryContext(ctx, retentionReviewCandidates)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RetentionReviewCandidatesRow
	for rows.Next() {
		var i RetentionReviewCandidatesRow
		if err := rows.Scan(&i.TenantID, &i.Category, &i.CandidateCount); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

